      {"t":"order","p":"Build kāge (crow)","a":["ಕಾ","ಗೆ"],"x":["ಖಾ"],"why":"ಕಾಗೆ starts with unaspirated ಕ, with no puff of air: ಕಾ, not ಖಾ."},
      {"t":"fill","q":"ಕೋ__","p":"kōṭe (fort)","a":["ಟೆ","ṭe"],"o":["ಠೆ","ಟಿ","ಡೆ"],"why":"ಕೋಟೆ ends in plain ṭe, with no puff: ಟೆ.","xr":["ṭhe","ṭi","ḍe"]},
      {"t":"fill","q":"__ಟ","p":"āṭa (game; play)","a":["ಆ","ā"],"o":["ಅ","ಊ","ಓ"],"why":"ಆಟ starts with the long vowel letter ಆ (ā).","xr":["a","ū","ō"]},
      {"t":"fill","q":"ಗಿ__","p":"giḍa (plant)","a":["ಡ","ḍa"],"o":["ಢ","ಟ","ಡಾ"],"why":"ಗಿಡ ends in plain ḍa: ಡ, with no puff and no vowel sign.","xr":["ḍha","ṭa","ḍā"]},
      {"t":"type","p":"Type kāḍu (forest)","a":["ಕಾ ಡು","ಕಾಡು","kā ḍu","kāḍu"],"hint":"kā + ḍu · long ā","x":["ಕ","ಢು"],"why":"ಕಾಡು has the plain retroflex ಡ, not ಢ, after a long vowel.","xr":["ka","ḍhu"]},
      {"t":"type","p":"Type kōṭe (fort)","a":["ಕೋ ಟೆ","ಕೋಟೆ","kō ṭe","kōṭe"],"hint":"kō + ṭe · long ō","x":["ಕೊ","ಠೆ"],"why":"ಕೋಟೆ starts with the long vowel ō: ಕೋ, not ಕೊ.","xr":["ko","ṭhe"]},
      {"t":"type","p":"Type kāge (crow)","a":["ಕಾ ಗೆ","ಕಾಗೆ","kā ge","kāge"],"hint":"kā + ge · no puff of air","x":["ಖಾ","ಘೆ"],"why":"ಕಾಗೆ uses unaspirated ಕ and ಗ, with no puff of air.","xr":["khā","ghe"]}
